-- Claves de protección de datos de ASP.NET Core (solo si DataProtection:PersistirEnBase = true).
-- Aplicar una vez con el usuario dueño de la base. Idempotente.

CREATE TABLE IF NOT EXISTS "DataProtectionKeys" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FriendlyName" text,
    "Xml" text,

    CONSTRAINT "PK_DataProtectionKeys" PRIMARY KEY ("Id")
);

COMMENT ON TABLE "DataProtectionKeys"
    IS 'Claves de ASP.NET Core Data Protection. Sin ellas, reiniciar el servidor cierra todas las sesiones.';

-- El rol de la aplicación necesita leer y escribir las claves.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ayudaya_app') THEN
        GRANT SELECT, INSERT, UPDATE, DELETE ON "DataProtectionKeys" TO ayudaya_app;
        GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO ayudaya_app;
    END IF;
END
$$;
